custom_css:
/* ===== 字体 ===== */
@font-face {
    font-family: "Jing Hua ";
    src: url("https://files.catbox.moe/138mza.ttf") format("truetype");
}
body {
    font-family: "Jing Hua ", sans-serif;
}

/* 分割线 */
hr {
    background-image: none;
    margin: 15px 0;
    height: auto;
    min-height: auto;
    border: 0;
    opacity: 0.8; /* 整体透明度调整为80% */
    text-align: center;
    position: relative;
}

hr::before {
    content: "ACTION";
    color: darkred;
    background-color: rgba(0, 0, 0, 0.05);
    padding: 2px 10px;
    border-radius: 4px;
    font-weight: bold;
    font-size: 0.9em;
    position: relative;
    z-index: 1;
}

hr::after {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    top: 50%;
    height: 1px;
    background: darkred;
    z-index: 0;
}
/* 引用 */
.mes_text q {
    color: var(--SmartThemeQuoteColor);
    background-color: rgba(69,69,69,0.4); /* 深灰色背景 */
    border-radius: 15px; /* 圆角效果 */
    padding: 0px 0px; /* 恢复适当的内边距 */
    display: inline;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}
/* 斜体 */
.mes_text em {
    color: var(--SmartThemeEmColor);
    text-decoration: underline;
    text-decoration-color: #666666; /* 暗灰色 */
    text-decoration-thickness: 2px; /* 2px粗的下划线 */
}

/* 代码块 */
.mes_text pre code, 
.mes_reasoning pre code {
    position: relative;
    display: block;
    overflow-x: auto;
    padding: 1em;
    width: 100%;
    box-sizing: border-box;

    /* 渐变背景 */
    background: #000000;

    /* 边框和圆角 */
    border-radius: 0;
    border: 1px solid rgba(75, 75, 75, 0.5);

    /* 文字样式 */
  font-family: 'Jing Hua ';
  src: url('https://files.catbox.moe/138mza.ttf') format('truetype');

font-family: 'Jing Hua ', monospace;
line-height: 1.5;
color: #E8E8E8; /* 浅色文字 */
font-size: 0.95em;

    /* 滚动条样式 */
    scrollbar-width: thin;
    scrollbar-color: #a0dcd7 transparent;

    /* 添加上下边框图片 */
    border-top: 5px solid transparent;
    border-bottom: 5px solid transparent;
    background-image: 
        url('https://i.postimg.cc/DwDJs3w5/211c41ab1f93e2a4e519fda62c61434a.png'),
        url('https://i.postimg.cc/DwDJs3w5/211c41ab1f93e2a4e519fda62c61434a.png');
    background-size: 60px 5px;
    background-repeat: repeat-x;
    background-position: top center, bottom center;
}

/* ===== 动画 ===== */
/* 移除原始伪元素 */
#load-spinner::before {
    content: none !important;
}

/* 创建新的自定义加载动画 */
#load-spinner::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 60px;
    height: 60px;
    background: url('https://i.postimg.cc/3JVWxyFN/IMG-2063.png') center/contain no-repeat;
    transform: translate(-50%, -50%);
    z-index: 1000;
    /* 调整旋转速度 - 15秒完成一圈 */
    animation: custom-spin 15s linear infinite;
}

/* 旋转动画关键帧 */
@keyframes custom-spin {
    0% {
        transform: translate(-50%, -50%) rotate(0deg);
    }
    100% {
        transform: translate(-50%, -50%) rotate(360deg);
    }
}

/* ===== 思维块美化 ===== */
.mes_reasoning_header {
    cursor: pointer;
    position: relative;
    user-select: none;
    margin: 0.5em 2px;
    padding: 7px 14px;
    padding-right: calc(0.7em + 14px);
    background-color: transparent;
    font-size: calc(var(--mainFontSize) * 0.9);
    color:#792b2b;
    align-items: baseline;
    /* Empty the content */
    font-size: 0 !important;
}

.mes_reasoning_header::before {
    content: "𝙼𝚘𝚟𝚒𝚎📹｜未完待续...";
    font-size: calc(var(--mainFontSize) * 0.9);
    display: inline;
}


/* ====== 气泡 ====== */
body.bubblechat .mes, body.bubblechat .mes[is_user="true"] {
    padding: 10px;
    border-radius: 0px;
    background-color: #1A1A1A;
    margin-bottom: 5px;
    border: 1px solid var(--SmartThemeBorderColor);
    max-width: 90%;
    position: relative; /* 为伪元素定位做准备 */
}

.mes {
    --swipeCounterHeight: 15px;
    --swipeCounterMargin: 5px;
    display: flex;
    align-items: flex-start;
    padding: 10px 10px 0;
    margin: 180px auto 0 auto;
    width: 90%;
    max-width: 90%;
    color: var(--SmartThemeBodyColor);
    position: relative;
    background-color: #1A1A1A;
}

.last_mes {
    margin-bottom: 0 !important;
}

/* 为所有气泡添加底部图片 */
.mes::after {
    content: "";
    position: absolute;
    bottom: 5px; 
    left: 50%;
    transform: translateX(-50%);
    width: 100px;
    height: 40px;
    background-image: url("https://i.postimg.cc/26V7HTQw/17c9144ec6531421f3dce88c8440d007.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 1;
}

/* 铅笔呼吸灯 */
.mes_button {
    cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    filter: drop-shadow(0px 0px 2px black);
    opacity: 1;
    padding: 1px 3px;
}

.fa-pencil-alt:before, .fa-pencil:before {
  content: "REC";
  color: #792b2b;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  width: 15px;
  height: 20px;
  font-size: 9px;
  font-weight: bold;
  vertical-align: middle;
  text-align: center;
  line-height: 1;
  animation: breathe 2s infinite ease-in-out;
}

@keyframes breathe {
  0%, 100% {
    opacity: 0.4;
    text-shadow: 0 0 5px rgba(121, 43, 43, 0.4);
  }
  50% {
    opacity: 1;
    text-shadow: 0 0 15px rgba(121, 43, 43, 0.8), 0 0 20px rgba(121, 43, 43, 0.6);
  }
}

/* 三个点 */
.fa-ellipsis-h:before, .fa-ellipsis:before {
  content: "";
  display: inline-block;
  width: 14px;
  height: 14px;
  background-color: #792b2b;
  border-radius: 50%;
  animation: breathe 2s infinite ease-in-out;
  vertical-align: middle;
}

@keyframes breathe {
  0%, 100% {
    opacity: 0.4;
  }
  50% {
    opacity: 1;
  }
}

/* 摄像头 */
.fa-camera-alt:before, .fa-camera:before {
    content: ""; /* 移除原有图标 */
    display: inline-block;
    width: 18px;
    height: 18px;
    background: url('https://i.postimg.cc/7Lf4c4Rz/IMG-2065.png') center/contain no-repeat;
    animation: breathe 2s infinite ease-in-out;
    vertical-align: middle;
}

@keyframes breathe {
  0%, 100% {
    opacity: 0.4;
  }
  50% {
    opacity: 1;
  }
}

/* 翻页 */
.swipe_left {
    right: auto;
    left: 5px;
}

.fa-chevron-right:before {
    content: "";
    display: inline-block;
    width: 20px;
    height: 20px;
    background-image: url("https://i.postimg.cc/3Jmgqs2W/1de547379de66d5632dbcfc692b4476f.png");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    vertical-align: middle;
}

.fa-chevron-left:before {
    content: "";
    display: inline-block;
    width: 20px;
    height: 20px;
    background-image: url("https://i.postimg.cc/QVGd5nMy/6d7932923a8e82075498a8bbb16758fe.jpg");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    vertical-align: middle;
}

/* 文本 */
.mes_text {
    padding-left: 5px;
    padding-top: 5px;
    padding-bottom: 30px;
    padding-right: 5px;
}


/* ====== 头像 ====== */
.mesAvatarWrapper {
    width: 300px;
    height: 160px;
    object-fit: cover;
    display: block;
    position: absolute;
    left: 50%;
    transform: translate(-50%);
    top: -175px; /* 微调位置使头像底部高于消息15px */
    center:50%;
}

.mesAvatarWrapper .avatar img {
width: 600%;
height: 300%;
object-fit: cover;
border-radius: inherit;
}

/* 覆盖图片 */
.mesAvatarWrapper::after {
    content: "";
    position: absolute;
    left: 50%;
    transform: translate(-50%);
    top: 0px;  /* 覆盖图片位置Y */
    width: 300px;
    height: 160px;
    background-image: url("https://i.postimg.cc/MH2vTK4k/IMG-2069.png");
    background-size: cover;
    background-position: center;
    z-index: 2; /* 覆盖头像 */
    pointer-events: none; /* 防止影响点击 */
}

.mes .mes_timer {
    cursor: default;
    opacity: 1;
    font-size: calc(var(--mainFontSize) * 0.75);
    font-weight: 600;
    text-align: left;
    position: absolute;
    left: 5px;
    top: 145px;
    z-index: 10;
}

.mes .mesIDDisplay {
    cursor: default;
    opacity: 1;
    font-size: calc(var(--mainFontSize) * 0.75);
    font-weight: 600;
    text-align: left;
    position: absolute;
    left: 50px;
    top: 145px;    
    z-index: 10;
}

.mes .tokenCounterDisplay {
    cursor: default;
    opacity: 1;
    font-size: calc(var(--mainFontSize) * 0.75);
    font-weight: 600;
    text-align: left;
    position: absolute;
    left: 100px;
    top: 145px;
    z-index: 10;
}


/* 时间戳位置 */
.mes .timestamp {
    font-size: calc(var(--mainFontSize) * 0.7);
    font-weight: 600;
    position: absolute; /* 绝对定位 */
    left: 50%; 
    top: -30px; /* Y轴偏移-40px */
    text-align: left; /* 左对齐 */
    white-space: nowrap; /* 防止换行 */
    z-index: 10; /* 确保显示在最前面 */
    opacity: 1; /* 保持原有透明度 */
}

/* 添加"DATE:"前缀 */
.mes .timestamp::before {
    content: " DATE :";
    display: inline;
}

.mes .name_text::before {
    content: "主演：";
    display: inline;
}
.mes .name_text {
    font-size: calc(var(--mainFontSize) * 0.7);
    position: absolute; /* 绝对定位 */
    left: 50%;
    transform: translate(-50%);
    top: -175px; /* Y轴向上偏移165px */
    text-align: center; 
    white-space: nowrap; /* 防止换行 */
    z-index: 10; /* 确保显示在最前面 */
    cursor: default;
    opacity: 1;
    font-weight: 600;
}

.mes_block {
  transform: none !important;
}

/* ===== 底部输入栏 ===== */
#qr--bar {
    outline: none;
    margin: 0;
    transition: 0.3s;
    opacity: 0.7;
    display: flex;
    align-items: center;
    justify-content: center;
    top:5px ;
    width: 100%;
    max-width: 100%;
    /* 修改高度为自适应 */
    height: auto;
    /* 设置最大高度并允许垂直滚动 */
    max-height: 30px; /* 保留原始高度作为最大高度 */
    /* 允许水平和垂直方向滚动 */
    overflow: auto; /* 替代原来的overflow-x和overflow-y */
    scrollbar-width: thin;
    scrollbar-color: #888 #f0f0f0;
}

/* 统一滚动条样式 */
#qr--bar::-webkit-scrollbar {
    width: 4px;  /* 垂直滚动条宽度 */
    height: 4px; /* 水平滚动条高度 */
}

#qr--bar::-webkit-scrollbar-track {
    background: #f0f0f0;
}

#qr--bar::-webkit-scrollbar-thumb {
    background-color: #888;
    border-radius: 2px;
}

#send_form {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    width: 100%;
    margin: 15px auto 20px auto; /* 上下边距15px */
    border: 1px solid var(--SmartThemeBorderColor);
    border-radius: 0; /* 四个角的圆角度数为0 */
    background-color: #282828; /* 颜色改为#282828 */
    backdrop-filter: blur(var(--SmartThemeBlurStrength));
    position: relative; /* 为内勾边定位做准备 */
}

/* 添加纯白内勾边 */
#send_form::before {
    content: "";
    position: absolute;
    top: 5px;
    left: 5px;
    right: 5px;
    bottom: 5px;
    border: 2px solid #757575;
    pointer-events: none; /* 确保不影响内部元素的交互 */
}
#nonQRFormItems {
    padding: 8px;
    border: 0;
    position: relative;
    background-position: center;
    display: flex;
    flex-direction: row;
    column-gap: 5px;
    font-size: var(--bottomFormIconSize);
    order: 25;
    margin: 0 auto; /* 水平居中 */
    transform-origin: center; /* 确保缩放以中心为基准 */
}
#nonQRFormItems {
    padding: 5px;
    border: 0;
    position: relative;
    background-position: center;
    display: flex;
    flex-direction: row;
    column-gap: 5px;
    font-size: var(--bottomFormIconSize);
    order: 25;
    width: 100%;

    /* 设置最小高度为30px，而不是固定高度 */
    min-height: 30px;
    align-items: center; /* 垂直居中 */
    overflow: hidden; /* 隐藏溢出内容 */
}

/* 输入框样式调整 */
#nonQRFormItems textarea {
    flex: 1;
    min-height: 30px; /* 最小高度与容器相同 */
    max-height: 100px; /* 最大高度限制 */
    resize: none; /* 禁止手动调整大小 */
    overflow-y: auto; /* 内容超出时显示滚动条 */
    line-height: normal; /* 保持正常行高 */
    padding: 5px; /* 适当内边距 */
    margin: 0;
    border: none;
    outline: none;
    background: transparent;
}

/* 字体图标容器固定大小 */
#nonQRFormItems .icon-container {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 30px;
    width: 30px; /* 固定宽度 */
    flex-shrink: 0; /* 防止图标被压缩 */
}

/* 字体图标等比例缩小70% */
.fa-paper-plane:before ,.fa-magic-wand-sparkles:before, .fa-wand-magic-sparkles:before ,.fa-bars:before, .fa-navicon:before {
    vertical-align: middle;
    text-align: center;
    transform: scale(0.7);
    transform-origin: center;
    display: inline-block;
    width: auto;
    height: auto;
}

#qr--bar > .qr--buttons .qr--button, #qr--popout > .qr--body > .qr--buttons .qr--button{
    transform: scale(0.9);
}


/* ===== 顶部 ===== */
.drawer-toggle .drawer-icon {
    transform: scale(0.7);
    transform-origin: center;
    display: inline-block;
    width: auto;
    height: auto;
}


/* ===== UI ===== */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background-color: #454545;
    margin-bottom: 4px;
    padding: 2px 5px 2px 20px;
    border: 1px solid var(--SmartThemeBorderColor);
    position: relative;
    border-radius: 0;
    /* 移除渐变和阴影相关属性 */
    box-shadow: none !important;
    background-image: none !important;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header::before,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::before,
#user-settings-block h4::before,
.standoutHeader::before {
    content: "";
    position: absolute;
    top: 3px;
    left: 3px;
    right: 3px;
    bottom: 3px;
    border: 1px solid #ADADAD;
    pointer-events: none;
    /* 移除伪元素的渐变和阴影 */
    box-shadow: none !important;
    background-image: none !important;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header::after,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::after,
#user-settings-block h4::after,
.standoutHeader::after {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 20px;
    height: 20px;
    background-image: url('https://i.postimg.cc/630mD4XM/IMG-2060.png');
    background-size: contain;
    background-repeat: no-repeat;
    z-index: 2;
    /* 确保图标元素没有阴影 */
    box-shadow: none !important;
}

/* 滑块 */
input[type="range"] {
    -webkit-appearance: none;
    appearance: none;
    margin: 0;
    padding: 0;
    width: 100%;
    height: 5px;
    background: var(--white50a);
    border-radius: 15px;
    background-size: 70% 100%;
    background-repeat: no-repeat;
    cursor: ew-resize;
}

/* Webkit浏览器滑块样式 */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 20px;
    background: url('https://i.postimg.cc/3JVWxyFN/IMG-2063.png') center/contain no-repeat;
    cursor: pointer;
    border: none;
}

/* Firefox浏览器滑块样式 */
input[type="range"]::-moz-range-thumb {
    width: 20px;
    height: 20px;
    background: url('https://i.postimg.cc/3JVWxyFN/IMG-2063.png') center/contain no-repeat;
    cursor: pointer;
    border: none;
}

/* 图标 */

.fa-bars:before, .fa-navicon:before {
    content: ""; /* 移除原有图标 */
    display: inline-block;
    width: 25px;
    height: 25px;
    background: url('https://i.postimg.cc/Pr1110zz/IMG-2070.png') center/contain no-repeat;
    vertical-align: middle;
}

.fa-magic-wand-sparkles:before, .fa-wand-magic-sparkles:before {
    content: ""; /* 移除原有图标 */
    display: inline-block;
    width: 25px;
    height: 25px;
    background: url('https://i.postimg.cc/tCnDTMxj/IMG-2068.png') center/contain no-repeat;
    vertical-align: middle;
}
